// Stable IDs retain the first twelve works and all existing local collections.
// Each new atlas has twelve square portraits; the final atlas contains four.
export function artAsset(index) {
  const sheet = Math.floor(index / 12);
  const cell = index % 12;
  const columns = sheet === 8 ? 2 : 4;
  const rows = sheet === 8 ? 2 : 3;
  return {
    src: sheet === 0 ? 'assets/portraits.png' : `assets/portraits-${String(sheet).padStart(2, '0')}.webp`,
    columns, rows, x: cell % columns, y: Math.floor(cell / columns)
  };
}

export function artStyle(index) {
  const {src, columns, rows, x, y} = artAsset(index);
  return `background-image:url("${src}");background-size:${columns * 100}% ${rows * 100}%;background-position:${x * 100 / (columns - 1)}% ${y * 100 / (rows - 1)}%`;
}
